# ---- the style-neutral check (the author's list), on scene and framing text
BANNED = r"\b(clay|claymation|plasticine|puppet|sculpt\w*|stop-motion|diorama|miniature|model|painted|illustrat\w*|comic|photograph\w*|render\w*|cute|rounded|simplified|chunky|soft|glossy|matte|pores|35mm|bokeh|depth of field|golden hour|dramatic|studio|haze|cinematic|mature|dignified|serious|playful|whimsical|child-friendly)\b"
for p in P:
    bad = re.findall(BANNED, p["scene"] + " " + FRAME[p["frame"]] + " " + FRAME["wide-eye"], flags=re.I)
    assert not bad, (p["id"], bad)

def frame_for(p):
    return FRAME["wide-eye"] if (p["kind"] == "field" and p["frame"] == "wide") else FRAME[p["frame"]]

OPEN_LEAD = "Handmade sculpted figures in a miniature diorama, photographed as a still of a crafted model, not a film frame."
OPEN_LEAD_NEW = "Handmade sculpted figures in a hand-built scene, photographed up close as a still of a crafted set, not a film frame."
OPEN_LIGHT = "Lighting and depth: slight miniature-set depth of field so the set reads as small and handmade. Soft, even studio lighting like a model on a display table, with gentle shadows and no dramatic contrast, no haze, no cinematic color grading."
OPEN_LIGHT_NEW = "Lighting and depth: slight shallow depth of field so the scene reads as small and handmade. Soft, even lighting with gentle shadows and no dramatic contrast, no haze, no cinematic color grading."

STYLE_CORE = STYLE.split("\n\n")[0].replace(" " + SETTING, "")
SETBUILD = {
    "street": "An ancient Judean village, roughly 2nd century, built as a miniature set of limestone houses with hand-carved stone texture, wooden doors, and a packed-earth road with scattered stones, low hills in the distance.",
    "interior": "The inside of an ancient Judean stone house, roughly 2nd century, built as a miniature interior with plastered walls, wooden beams, and a tamped-earth floor.",
    "field": "An ancient Judean landscape, roughly 2nd century, hand-built with hand-carved stone walls, packed-earth ground, tufts of grass, and scattered stones, continuing back to distant hills.",
}
LIGHT = "slight miniature-set depth of field so the set reads as small and handmade. Soft, even studio lighting like a model on a display table, with gentle shadows and no dramatic contrast, no haze, no cinematic color grading. Muted earthy palette of ochre, terracotta, dusty blue, and stone grey."
LIGHT_OPEN = "slight shallow depth of field so the scene reads as small and handmade. Soft, even lighting with gentle shadows and no dramatic contrast, no haze, no cinematic color grading. Muted earthy palette of ochre, terracotta, dusty blue, and stone grey."
# v5: the author's Chat version, which gave the lifelike jug picture, has no clay/illustrated words in the avoid line and no posing paragraph
AVOID5 = "Avoid: photorealism, film still, cinematic lighting, atmospheric haze, realistic skin pores, plush or felt toy look, glossy eyes, cute or rounded features, bright toy colors, text, watermark. Aspect ratio 3:2 landscape."

def build_prompt(p):
    openair = p["kind"] == "field" or p["frame"] == "wide"
    lead = STYLE_CORE.replace(OPEN_LEAD, OPEN_LEAD_NEW) if openair else STYLE_CORE
    parts = [lead]
    if p["animals"]: parts.append(ANIMALS)
    if p["child"]: parts.append(CHILD)
    body = p["scene"][len("Scene: "):] if p["scene"].startswith("Scene: ") else p["scene"]
    body = body[0].upper() + body[1:]
    parts.append("Scene: " + SETBUILD[p["kind"]] + " " + body)
    fr = frame_for(p); fr = fr[0].lower() + fr[1:]
    comp = "Composition and light: " + fr.rstrip(".") + ", " + (LIGHT_OPEN if openair else LIGHT)
    if openair: comp += " " + FILL
    parts.append(comp)
    parts.append(AVOID5)
    return "\n\n".join(parts)

out = ["""# Older-audience pictures in the sculpted-diorama style: prompts v6 (2026-10-31)

v6: the four slipping or falling scenes (3:1b, 3:2a, 3:3, 3:4) now show the moment just AFTER the fall, with the body on the ground (a figure caught in mid-air always came out as a stiff doll, while the sprawled man in 3:1a and the one-footed woman in 3:2b looked real). v5: rebuilt on the structure of the Chat prompt that gave the lifelike jug picture (style paragraph, then Scene with the setting first and ages for the people, then 'Composition and light', then its shorter Avoid line). Removed: the Posing paragraph (it named dolls, toys and figurines, which the model draws when it is told about them), the extra style paragraphs, and 'clay look' and 'comic-book or illustrated style' from the avoid line. v4: the figures looked like stiff dolls (2:2a, 5:5, 3:11a). Every new-chat prompt now has a Posing paragraph in the style block (candid, mid-moment, weight and balance, no figurine stance, real faces), and the action scenes describe the body positions (which foot slides, how the torso leans, what each hand does). Optional, strongest fix: attach your 3:1a picture as a reference (see the REFERENCE LINE below). v3: every dead animal (5:1 cow and calf, 5:5 and 5:6 ox) is shown with an X marked on each closed eye, as in the clay set; the 5:5 and 5:6 ox is 'a male ox with no udder' (Gemini drew a cow). v2: open-air and wide scenes (12 of the 29, marked below by the line 'The set fills the whole frame') no longer open with 'miniature diorama ... crafted model' or say 'model on a display table', and carry a line that the set fills the frame; the pasture in 3:11 is not boxed in. Street, interior and close scenes are unchanged from v1 (3:1a worked).

For every picture that already has a graphic-novel (older-audience) version: Bava Kamma 3 (14 pictures), Bava Kamma 5 (5) and Bava Metzia 1 (10). Teen/adult track only: the younger-track (claymation) style block was not pasted into the style file, and the younger pictures stay as they are. The other chapters of Bava Kamma have no older pictures yet, so they are not here.

Source of the scenes: the approved graphic-novel prompts (BK 3 v3 with its fixes folded in, BK 5 and BM 1 v1; BK 5:1 from the style test), made style-neutral. The style block, framing lines, avoid line and the three allowed adjustments (animals, a child, an interior or open field) are the style file's, word for word.

How to use: paste each PASTE block into a NEW Gemini chat. Where the heading says "same chat, edit", paste it into the chat that made the previous picture of its set; those edit lines carry no style block, because the picture already has it. Send me the pictures; the badges and tags are re-placed on the new pictures (the old positions belong to the graphic-novel pictures).

Changes from the graphic-novel scenes, for review:
1. Every adult man now wears a head covering (a plain cloth cap in a stated colour, or the hat or cap he already had), and every woman a head covering (added to the 3:3 walker, the 3:2 traveller, the grey-haired owner in 3:11 and the 1:5b daughter). Bald and 'bald head' wording is gone for this reason. Children are left bare-headed (the small child in 1:5a): decision pending.
2. Injuries are shown at the restrained level the style file asks for, but still visibly: a cut with a line of blood (3:1a), a chip in the forehead with a trickle of blood (3:7), a torn gash in the small ox (3:11) and a gash in the cow (5:1), never gory.
3. The words in the scenes that name a medium or a finish (painted, cartoon, clay, drawn in the same style) are gone. No animal has an expression (the 5:2a cow no longer 'looks guilty').
4. Case-critical numerals and the question marks stay where the case needs them (5:1, 5:5, 5:6, 1:7), because the case depends on them: the style file says no text, so each of these scenes says exactly what text is allowed. Check them first. The framed boxes are kept as plain rectangles above the scene; if they fight the diorama look, the fix is to make them small display windows.
5. Recurring cast: the 3:5 pair keep the same clothes across 5s/5a/5b/5c, the 5:2 pair, the 1:1, 1:3 and 1:4 pairs keep their casts; each distinct person has his own colour, beard or cap.
6. REFERENCE LINE (optional): attach your best picture (3:1a, the jug) to the chat before pasting a new-chat prompt, and add this as the first line: "Attached is a reference picture. Match its style, lighting, figure scale and lifelike body posture exactly, but draw ONLY the new scene below, with entirely different people, setting and objects." Skip it for edits (same chat).
"""]
for p in P:
    out.append(f"\n## {p['id']}: {p['title']}\n\n")
    if p["edit"]:
        out.append(f"{p['scene']}\n")
        # an edit goes into the same chat: no style block
        out[-1] = f"PASTE (edit, same chat; the style stays):\n```\n{p['scene']}\n```\n"
    else:
        out.append(f"PASTE (new chat):\n```\n{build_prompt(p)}\n```\n")
open("data/diorama_prompts_bk3-bk5-bm1_v6.md", "w").write("".join(out))
print(len(P), "prompts;", sum(1 for p in P if p["edit"]), "edits")
